import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';

const CompleteUploadPageFixed = () => {
  const navigate = useNavigate();
  const [files, setFiles] = useState([]);
  const [uploading, setUploading] = useState(false);

  const handleFileUpload = (e) => {
    const uploadedFiles = Array.from(e.target.files);
    setFiles(uploadedFiles);
  };

  const handleGenerateData = () => {
    setUploading(true);
    setTimeout(() => {
      const mockCompanyData = {
        company: "Tech Innovations Pvt Ltd",
        revenue: "15.5",
        industry: "Technology",
        financial_metrics: {
          monthly_revenue: "12.8",
          monthly_profit: "2.1",
          cash_flow: "3.2",
          total_liabilities: "45.2",
          equity: "125.3"
        }
      };

      localStorage.setItem('companyData', JSON.stringify({
        is_multi_company: false,
        companies: [mockCompanyData]
      }));

      setUploading(false);
    }, 2000);
  };

  return (
    <div style={{ 
      minHeight: '100vh', 
      background: 'linear-gradient(135deg, #1e40af 0%, #0f766e 50%, #0891b2 100%)',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      color: 'white'
    }}>
      <div style={{ textAlign: 'center', maxWidth: '800px' }}>
        <div style={{ fontSize: '48px', marginBottom: '24px' }}>🏦</div>
        <h1 style={{ fontSize: '32px', fontWeight: 'bold', marginBottom: '16px' }}>
          AI Credit Decisioning Engine
        </h1>
        <p style={{ fontSize: '18px', marginBottom: '32px', color: 'rgba(255,255,255,0.8)' }}>
          Upload your financial documents to get dynamic credit analysis
        </p>

        <div style={{
          background: 'rgba(255, 255, 255, 0.1)',
          backdropFilter: 'blur(20px)',
          borderRadius: '20px',
          padding: '32px',
          border: '2px dashed rgba(255, 255, 255, 0.3)',
          textAlign: 'center',
          marginBottom: '32px'
        }}>
          <input
            type="file"
            multiple
            onChange={handleFileUpload}
            style={{
              display: 'none'
            }}
            id="file-upload"
          />
          <label
            htmlFor="file-upload"
            style={{
              display: 'inline-block',
              padding: '16px 32px',
              background: 'linear-gradient(135deg, #3b82f6, #2563eb)',
              color: 'white',
              borderRadius: '12px',
              cursor: 'pointer',
              fontSize: '16px',
              fontWeight: '600',
              transition: 'all 0.3s ease',
              boxShadow: '0 4px 6px rgba(59, 130, 246, 0.2)'
            }}
          >
            📤 Choose Files
          </label>
        </div>

        {files.length > 0 && (
          <div style={{ marginBottom: '24px' }}>
            <h3 style={{ fontSize: '18px', marginBottom: '16px', color: 'white' }}>
              Selected Files:
            </h3>
            {files.map((file, index) => (
              <div key={index} style={{
                background: 'rgba(255, 255, 255, 0.1)',
                padding: '12px',
                borderRadius: '8px',
                marginBottom: '8px',
                display: 'flex',
                justifyContent: 'space-between',
                alignItems: 'center'
              }}>
                <span>{file.name}</span>
                <button
                  onClick={() => setFiles(files.filter((_, i) => i !== index))}
                  style={{
                    background: '#ef4444',
                    color: 'white',
                    border: 'none',
                    borderRadius: '6px',
                    padding: '6px 12px',
                    cursor: 'pointer',
                    fontSize: '12px'
                  }}
                >
                  Remove
                </button>
              </div>
            ))}
          </div>
        )}

        <button
          onClick={handleGenerateData}
          disabled={uploading || files.length === 0}
          style={{
            background: uploading 
              ? '#6b7280' 
              : 'linear-gradient(135deg, #10b981, #059669)',
            color: 'white',
            border: 'none',
            borderRadius: '12px',
            padding: '16px 32px',
            cursor: uploading ? 'not-allowed' : 'pointer',
            fontSize: '16px',
            fontWeight: '600',
            transition: 'all 0.3s ease',
            boxShadow: '0 4px 6px rgba(16, 185, 129, 0.2)',
            opacity: uploading ? 0.7 : 1
          }}
        >
          {uploading ? (
            <>
              <div style={{
                width: '20px',
                height: '20px',
                border: '2px solid white',
                borderTop: '2px solid transparent',
                borderRadius: '50%',
                animation: 'spin 1s linear infinite',
                marginRight: '12px',
                display: 'inline-block',
                verticalAlign: 'middle'
              }}></div>
              Processing...
            </>
          ) : (
            'Generate Dynamic Analysis'
          )}
        </button>

        {files.length > 0 && (
          <div style={{ marginTop: '24px' }}>
            <button
              onClick={() => navigate('/dashboard')}
              style={{
                background: 'linear-gradient(135deg, #3b82f6, #2563eb)',
                color: 'white',
                border: 'none',
                borderRadius: '12px',
                padding: '16px 32px',
                cursor: 'pointer',
                fontSize: '16px',
                fontWeight: '600',
                transition: 'all 0.3s ease',
                boxShadow: '0 4px 6px rgba(59, 130, 246, 0.2)',
                marginRight: '12px'
              }}
            >
              📊 View Static Dashboard
            </button>
            <button
              onClick={() => navigate('/dynamic-dashboard')}
              style={{
                background: 'linear-gradient(135deg, #10b981, #059669)',
                color: 'white',
                border: 'none',
                borderRadius: '12px',
                padding: '16px 32px',
                cursor: 'pointer',
                fontSize: '16px',
                fontWeight: '600',
                transition: 'all 0.3s ease',
                boxShadow: '0 4px 6px rgba(16, 185, 129, 0.2)',
                marginRight: '12px'
              }}
            >
              🚀 View Dynamic Dashboard
            </button>
            <button
              onClick={() => navigate('/research')}
              style={{
                background: 'linear-gradient(135deg, #8b5cf6, #7c3aed)',
                color: 'white',
                border: 'none',
                borderRadius: '12px',
                padding: '16px 32px',
                cursor: 'pointer',
                fontSize: '16px',
                fontWeight: '600',
                transition: 'all 0.3s ease',
                boxShadow: '0 4px 6px rgba(139, 92, 246, 0.2)'
              }}
            >
              🔍 Research Insights
            </button>
            <button
              onClick={() => navigate('/cam-preview')}
              style={{
                background: 'linear-gradient(135deg, #06b6d4, #0891b2)',
                color: 'white',
                border: 'none',
                borderRadius: '12px',
                padding: '16px 32px',
                cursor: 'pointer',
                fontSize: '16px',
                fontWeight: '600',
                transition: 'all 0.3s ease',
                boxShadow: '0 4px 6px rgba(6, 182, 212, 0.2)'
              }}
            >
              📄 CAM Preview
            </button>
          </div>
        )}
      </div>
    </div>
  );
};

export default CompleteUploadPageFixed;
